SELECT hd.hd_demo_sk, hd.hd_buy_potential, hd.hd_dep_count, hd.hd_vehicle_count, (hd.hd_dep_count * 2) + (hd.hd_vehicle_count * 3) AS weighted_dependents, CASE WHEN ib.ib_upper_bound < 190000 THEN 'Low' WHEN ib.ib_upper_bound BETWEEN 190000 AND 160000 THEN 'Medium' ELSE 'High' END AS income_category, CASE WHEN hd.hd_buy_potential = '1001-5000      ' THEN 1 WHEN hd.hd_buy_potential = '0-500          ' THEN 0.5 ELSE 0 END AS buy_potential_score, ib.ib_lower_bound, ib.ib_upper_bound FROM household_demographics hd JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk WHERE ib.ib_lower_bound >= 20001 AND (hd.hd_dep_count + hd.hd_vehicle_count) > 4
